MC.registerPack({"id":"drax","cards":[{"id":"19001a","name":"드랙스","en":"* Drax","type":"hero","enc":false,"unique":true,"hp":14,"atk":1,"thw":1,"def":2,"hs":4,"tr":["GUARDIAN"],"traits":["가디언"],"text":"드랙스는 자신에게 놓인 복수 카운터마다 공격 +1을 받습니다.\n<b>반응:</b> 빌런이 드랙스를 공격한 후, 이 카드에 복수 카운터를 1만큼 놓습니다(최대 3까지). 그럴 수 없다면, 카드 1장을 뽑습니다."},{"id":"19001b","name":"드랙스","en":"* Drax","type":"alter","enc":false,"unique":true,"hp":14,"rec":4,"hs":6,"tr":["OUTLAW"],"traits":["무법자"],"text":"<b>강제 반응:</b> 당신이 이 형태로 변신한 후, 드랙스에게서 복수 카운터를 모두 제거합니다. 이렇게 제거한 복수 카운터마다 드랙스가 입은 피해 2점을 치료합니다."},{"id":"19002","name":"맨티스","en":"* Mantis","type":"ally","enc":false,"unique":true,"hp":3,"atk":1,"atkStar":true,"atkCons":2,"thw":2,"thwStar":true,"cost":2,"res":"G","cls":"Hero","tr":["GUARDIAN"],"traits":["가디언"],"text":"<b>행동:</b> 맨티스를 소진하고 맨티스에게 피해 1점을 입힘 → 아이덴티티 하나가 입은 피해 3점을 치료."},{"id":"19003","name":"\"덤벼라, 겁쟁이!\"","en":"\"Fight Me, Coward!\"","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Hero","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 당신의 히어로를 준비하고 카드 1장을 뽑습니다. 빌런이 당신을 공격합니다."},{"id":"19004","name":"협박","en":"Intimidation","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["THWART"],"traits":["저지"],"text":"<b>히어로 행동</b><i>(저지)</i>: 음모 하나에서 위협을 X만큼 제거합니다. X는 당신의 공격 수치와 같습니다."},{"id":"19005","name":"단검 도약","en":"Knife Leap","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"드랙스에게 놓인 복수 카운터마다 이 카드를 플레이하는 비용이 1 감소합니다.\n<b>히어로 난입</b>: 당신이 기본 공격을 할 때, 그 공격에 대해 당신은 공격 +5를 받습니다. 그 공격은 압살과 관통을 얻습니다."},{"id":"19006","name":"받아넘기기","en":"Parry","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":["DEFENSE"],"traits":["방어"],"text":"<b>히어로 난입</b><i>(방어)</i>: 당신이 피해를 입으려 할 때, 그 피해에서 X점을 방지합니다. X는 당신의 공격 수치의 2배입니다."},{"id":"19007","name":"앙갚음","en":"Payback","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Hero","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 반응</b><i>(공격)</i>: 빌런이 당신을 공격한 후, 빌런에게 피해 X점을 입힙니다. X는 당신의 공격 수치와 같습니다."},{"id":"19008","name":"드랙스의 단검","en":"* Drax's Knife","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"G","cls":"Hero","tr":["WEAPON"],"restricted":1,"traits":["무기"],"text":"한정 (플레이어마다 한정 카드는 최대 2장.)\n히어로 형태인 동안, 드랙스는 공격 +1을 받습니다."},{"id":"19009","name":"드랙스의 또 다른 단검","en":"* Drax's Other Knife","type":"upgrade","enc":false,"unique":true,"cost":1,"res":"G","cls":"Hero","tr":["WEAPON"],"restricted":1,"traits":["무기"],"text":"한정 (플레이어마다 한정 카드는 최대 2장.)\n히어로 형태인 동안, 드랙스는 반격 1을 얻습니다."},{"id":"19010","name":"드위 티트 숙달","en":"DWI Theet Mastery","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"B","cls":"Hero","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 반응</b>: 드랙스가 기본 공격을 한 후, 카드 1장을 뽑습니다."},{"id":"19011","name":"죽기엔 너무 고집불통","en":"Too Stubborn to Die","type":"upgrade","enc":false,"unique":false,"cost":2,"res":"B","cls":"Hero","tr":["CONDITION"],"traits":["상태"],"text":"<b>히어로 난입</b>: 드랙스가 격파되려 할 때, 대신 그의 생명력 다이얼을 4로 맞추고, 그를 일상 형태로 변신시킨 다음, 이 카드를 게임에서 제거합니다."},{"id":"19012","name":"마터","en":"* Martyr","type":"ally","enc":false,"sub":"파일라벨","unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":4,"res":"Y","cls":"Protection","tr":["GUARDIAN"],"traits":["가디언"],"text":"<b>반응:</b> 마터가 공격을 수행하여 부수적 피해를 입은 후, 그 공격으로 적이 격파되었다면, 마터에게 강인함 상태 카드를 줍니다."},{"id":"19013","name":"문드래곤","en":"* Moondragon","type":"ally","enc":false,"sub":"헤더 더글러스","unique":true,"hp":2,"atk":1,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"B","cls":"Protection","tr":["GUARDIAN"],"traits":["가디언"],"text":"<b>행동:</b> 문드래곤을 소진하고 버림 → 하수인 하나를 선택하고, 그 하수인이 당신이 선택한 다른 적 하나를 공격하게 함."},{"id":"19014","name":"카운터 펀치","en":"Counter-Punch","type":"event","enc":false,"unique":false,"cost":0,"res":"R","cls":"Protection","tr":["ATTACK"],"traits":["공격"],"text":"<b>반응</b>(공격): 당신의 히어로가 적의 공격을 방어한 후, 공격한 적에게 당신 히어로의 공격 수치만큼 피해를 입힙니다.","link":"01077"},{"id":"19015","name":"튕겨내기","en":"Deflection","type":"event","enc":false,"unique":false,"cost":2,"res":"B","cls":"Protection","tr":["SKILL"],"traits":["기술"],"text":"<b>히어로 난입</b>: 아이덴티티 하나가 공격으로 피해를 입으려 할 때, 그 피해를 5점까지 방지합니다. 이렇게 방지한 피해만큼 당신의 덱 맨 위에서 카드를 버립니다."},{"id":"19016","name":"거친 타격","en":"Hard Knocks","type":"event","enc":false,"unique":false,"cost":3,"res":"R","cls":"Protection","tr":["ATTACK"],"traits":["공격"],"text":"<b>히어로 행동</b><i>(공격)</i>: 적 하나에게 피해 4점을 입힙니다. 이 공격으로 그 적이 격파되면, 당신의 히어로에게 강인함 상태 카드를 줍니다."},{"id":"19017","name":"선제 일격","en":"Leading Blow","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Protection","tr":["TACTIC"],"traits":["전술"],"text":"<b>히어로 난입</b>: 당신의 히어로가 기본 공격을 할 때, 조우 덱 맨 위 카드 1장을 버림 → 그 공격에 대해 당신의 히어로의 공격 수치를 그 카드에 인쇄된 강화 아이콘 수만큼 감소. 그래도 그 공격이 피해를 입힌다면, 당신의 히어로를 준비."},{"id":"19018","name":"제압","en":"Subdue","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Protection","tr":[],"traits":[],"text":"<b>히어로 난입</b>: 적이 공격을 개시할 때, 그 적은 그 공격에 대해 공격 -3을 받습니다."},{"id":"19019","name":"불굴의 정신","en":"Indomitable","type":"upgrade","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Protection","tr":["CONDITION"],"traits":["상태"],"text":"<b>반응</b>: 당신의 히어로가 방어한 후, 불굴의 정신을 버림 → 당신의 히어로를 준비.","link":"01082"},{"id":"19020","name":"가모라","en":"* Gamora","type":"ally","enc":false,"unique":true,"hp":3,"atk":2,"atkStar":true,"thw":1,"thwStar":true,"cost":3,"res":"Y","cls":"Basic","tr":["GUARDIAN"],"traits":["가디언"],"text":"당신의 아이덴티티가 [[가디언]] 특성을 가진 경우에만 플레이합니다.\n<b>히어로 반응</b>: 가모라가 공격하거나 저지한 후, 이벤트 카드를 버릴 때까지 당신의 덱 맨 위에서 카드를 버린 다음, 그 카드를 당신의 손에 더합니다."},{"id":"19021","name":"탄탄한 훈련","en":"Athletic Conditioning","type":"event","enc":false,"unique":false,"cost":1,"res":"B","cls":"Basic","tr":[],"traits":[],"text":"<b>히어로 행동</b>: 당신의 히어로에게 놓인 기절 또는 혼란 상태 카드 1장을 버립니다.","link":"13034"},{"id":"19022","name":"에너지","en":"Energy","type":"resource","enc":false,"unique":false,"res":"YY","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01088"},{"id":"19023","name":"천재","en":"Genius","type":"resource","enc":false,"unique":false,"res":"BB","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01089"},{"id":"19024","name":"힘","en":"Strength","type":"resource","enc":false,"unique":false,"res":"RR","cls":"Basic","tr":[],"maxDeck":1,"traits":[],"text":"덱마다 최대 1장.","link":"01090"},{"id":"19025","name":"다른 삶의 기억","en":"Memories of Another Life","type":"obligation","enc":true,"set":"Drax","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b><i>드랙스 플레이어에게 이 카드를 줍니다.</i></b>\n당신은 일상 형태로 카드를 뒤집어도 됩니다. 다음 중 하나를 선택합니다.\n• 당신의 일상을 소진 → 다른 삶의 기억을 게임에서 제거.\n• 당신은 기절합니다. 이미 기절 상태라면, 이 카드는 쇄도를 얻습니다. 이 의무 카드를 버립니다."},{"id":"19026","name":"약자 솎아내기","en":"Cull the Weak","type":"side","enc":true,"set":"Drax Nemesis","unique":false,"boost":2,"start":2,"startStar":true,"tr":[],"traits":[],"text":"각 적은 공격 +2를 받습니다"},{"id":"19027","name":"요탓 더 디스트로이어","en":"* Yotat the Destroyer","type":"minion","enc":true,"set":"Drax Nemesis","unique":true,"hp":5,"atk":3,"sch":1,"boost":3,"retaliate":1,"tr":["BRUTE"],"guard":1,"nemesis":true,"traits":["야만"],"text":"경호. 반격 1.\n<i>(드랙스의 숙적 하수인)</i>"},{"id":"19028","name":"도전 수락","en":"Challenge Accepted","type":"attachment","enc":true,"set":"Drax Nemesis","unique":false,"boost":1,"plus":{"atk":2},"surge":1,"tr":[],"traits":[],"text":"쇄도.\n공격 수치가 가장 높은 적에게 장착합니다.\n<b>강제 반응</b>: 드랙스가 한 번의 공격으로 장착된 적에게 피해를 4점 이상 입힌 후, 이 카드를 버립니다."},{"id":"19029","name":"\"널 박살 내겠다!\"","en":"\"I Will Destroy You!\"","type":"treachery","enc":true,"set":"Drax Nemesis","unique":false,"boost":2,"tr":[],"traits":[],"text":"<b>공개될 때(일상)</b>: 이 카드는 쇄도를 얻습니다.\n<b>공개될 때 (히어로)</b>: 요탓 더 디스트로이어가 공격 +1을 받은 채 당신을 공격합니다. 이렇게 이루어진 공격이 없다면, 빌런이 당신을 공격합니다."},{"id":"19030","name":"\"덤벼!\"","en":"\"Bring It!\"","type":"event","enc":false,"unique":false,"cost":0,"res":"Y","cls":"Aggression","tr":[],"traits":[],"text":"페이즈당 최대 1번.\n<b>히어로 행동</b>: 당신과 교전 중인 하수인마다 카드 1장을 뽑습니다."},{"id":"19031","name":"\"잡아 봐!\"","en":"\"Think Fast!\"","type":"event","enc":false,"unique":false,"cost":1,"res":"Y","cls":"Justice","tr":[],"traits":[],"text":"당신의 아이덴티티가 [[가디언]] 특성을 가진 경우에만 플레이합니다.\n<b>히어로 행동</b>: 당신이 피해 1점을 입습니다. 빌런을 혼란에 빠뜨립니다."},{"id":"19032","name":"재정비","en":"Regroup","type":"support","enc":false,"unique":false,"cost":1,"res":"B","cls":"Leadership","tr":["TACTIC"],"traits":["전술"],"text":"<b>난입</b>: 동료가 적의 공격으로 격파될 때, 그 동료를 버리는 대신 소유자의 손으로 되돌립니다.\n<b>강제 난입</b>: 라운드가 끝날 때, 이 카드를 버립니다."}]});
